  function videoCameraById(id) { return videoCameras.filter(function(camera){return camera.id===id;})[0] || videoCameras[0]; }
  function videoTile(camera,index) {
    if(!camera)return '<div class="isc-video-tile empty"><span>＋</span><small>选择摄像机</small></div>';
    var online=camera.online||camera.id==="CAM-082"&&videoState.recovered;
    var active=camera.id===videoState.selectedCamera?' active':'';
    var sceneClass=' scene-'+camera.scene;
    if(!camera.permission)return '<button class="isc-video-tile denied'+active+'" data-action="video-camera" data-camera="'+camera.id+'" data-permission="false"><span class="tile-title">'+camera.id+'　'+camera.name+'</span><div class="video-denied-state"><b>⊘</b><strong>无视频查看权限</strong><small>需向视频管理员申请该组织权限</small></div></button>';
    if(!online)return '<button class="isc-video-tile offline'+active+'" data-action="video-camera" data-camera="'+camera.id+'" data-permission="true"><span class="tile-title">'+camera.id+'　'+camera.name+'</span><div class="video-error-state"><b>!</b><strong>视频连接异常</strong><small>iSC 返回：设备离线（340015）</small><em data-action="video-retry">重新连接</em></div></button>';
    return '<button class="isc-video-tile'+active+sceneClass+'" data-action="video-camera" data-camera="'+camera.id+'" data-permission="true"><span class="tile-title"><i></i>'+camera.id+'　'+camera.name+'</span><span class="tile-clock">'+(videoState.mode==="playback"?'录像 '+videoState.playbackTime:'LIVE　2026-10-26 14:36:'+(20+index))+'</span><span class="tile-channel">iSC · 主码流 1080P</span><span class="tile-focus">'+(camera.id===videoState.selectedCamera?'当前窗口':'点击切换')+'</span></button>';
  }
