    var tree=floors.map(function(floor){var floorCameras=videoCameras.filter(function(camera){return camera.floor===floor;}),open=videoState.floorOpen[floor];return '<section class="isc-tree-group"><button class="isc-floor-toggle" data-action="video-floor-toggle" data-floor="'+floor+'"><span>'+(open?'⌄':'›')+'　'+floor+'</span><em>'+floorCameras.length+'</em></button>'+(open?floorCameras.map(function(camera){var online=camera.online||camera.id==="CAM-082"&&videoState.recovered;return '<button class="isc-camera-node '+(!camera.permission?'denied ':'')+'" data-action="video-open" data-camera="'+camera.id+'" data-permission="'+camera.permission+'"><i class="'+(online?'online':'offline')+'"></i><span>'+camera.name+'<small>'+camera.id+' · '+camera.area+'</small></span><em>'+(camera.permission?(online?'在线':'离线'):'无权限')+'</em></button>';}).join(''):'')+'</section>';}).join('');
    var floorCameras=videoCameras.filter(function(camera){return camera.floor===videoState.selectedFloor;}),otherCameras=videoCameras.filter(function(camera){return camera.floor!==videoState.selectedFloor;}),layoutSlots=floorCameras.concat(otherCameras).slice(0,videoState.layout);
    var cards=layoutSlots.map(function(camera){var online=camera.online||camera.id==="CAM-082"&&videoState.recovered;return '<article class="isc-camera-card '+(!online?'offline ':'')+(!camera.permission?'denied ':'')+'"><div class="camera-cover scene-'+camera.scene+'"><span>'+camera.id+'</span><em>'+(camera.permission?(online?'在线':'离线'):'无权限')+'</em></div><div class="camera-card-info"><span><b>'+camera.name+'</b><small>'+camera.floor+' · '+camera.area+' · 主码流1080P</small></span><button data-action="video-open" data-camera="'+camera.id+'" data-permission="'+camera.permission+'">'+(camera.permission?'查看视频':'申请权限')+'</button></div></article>';}).join('');
